#include <iostream>
using namespace std;

long long int power_mod(long long int base, long long int exponent) {
    long long int modulus = 1000000007;
    long long int result = 1;
    while (exponent > 0) {
        result = (result * base) % modulus;
        exponent--;
    }
    return result;
}

int main() {
    long long int p, k, ord = 1;
    cin >> p >> k;
    if (k == 0) {
        ord = p - 1;
    } else if (k == 1) {
        ord = p;
    } else {
        long long int cur = k;
        while (true) {
            cur = (cur * k) % p;
            ord++;
            if (cur == 1) break;
        }
        ord = (p - 1) / ord;
    }
    cout << power_mod(p, ord) << endl;
    return 0;
}
